<?php
require_once __DIR__.'/_header.php';require_admin();$page_title='Analytics';
$views=db()->query("SELECT COUNT(*) FROM analytics_events WHERE event_type='view'")->fetchColumn();$popular=db()->query("SELECT s.title,COUNT(*) views FROM analytics_events e JOIN stories s ON s.id=e.story_id WHERE e.event_type='view' GROUP BY e.story_id ORDER BY views DESC LIMIT 10")->fetchAll();$activity=db()->query('SELECT a.name,l.action,l.details,l.created_at FROM admin_activity l LEFT JOIN admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 20')->fetchAll();
?><div class="content"><div class="grid"><div class="card"><h3>Story views</h3><div class="stat"><?=e((string)$views)?></div></div><div class="card"><h3>Open corrections</h3><div class="stat"><?=e((string)db()->query("SELECT COUNT(*) FROM correction_reports WHERE status='OPEN'")->fetchColumn())?></div></div></div><div class="card" style="margin-top:20px"><h2>Popular stories</h2><?php foreach($popular as $row):?><p><?=e($row['title'])?> · <?=e((string)$row['views'])?> views</p><?php endforeach;?></div><div class="card" style="margin-top:20px"><h2>Admin activity</h2><?php foreach($activity as $row):?><p><?=e($row['created_at'])?> · <?=e($row['name']??'Unknown')?> · <?=e($row['action'])?> <?=e($row['details']??'')?></p><?php endforeach;?></div></div>
